import {GROCERY_CATALOG as CATALOG, RECIPES, recipeMatch} from './data.js';
import {rescueRecipes,weeklyMealPlan,expiryDigest} from './smart-kitchen.js';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = {
  home:'M3 10 12 3l9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1Z',
  fridge:'M5 3h14v18H5z M5 10h14 M8 6v1 M8 13v3',
  recipes:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4z M13 7a3 3 0 0 1 3-3h5v15h-4a4 4 0 0 0-4 2',
  bag:'M4 7h16l1 14H3z M8 8V6a4 4 0 0 1 8 0v2',
  settings:'m9 3-.5 3-2 1-2.5-1-2 3 2 2v2l-2 2 2 3 2.5-1 2 1 .5 3h4l.5-3 2-1 2.5 1 2-3-2-2v-2l2-2-2-3-2.5 1-2-1-.5-3Z M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6',
  plus:'M12 5v14 M5 12h14', search:'m21 21-5-5 M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14',
  arrow:'M4 12h15 M14 7l5 5-5 5', chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6',
  leaf:'M4 16C2 6 11 3 21 3c0 11-5 18-13 15 M3 22 16 9',
  clock:'M12 8v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',
  bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',
  user:'M8 7a4 4 0 1 0 8 0 4 4 0 0 0-8 0 M4 21v-3a8 8 0 0 1 16 0v3',
  check:'m5 12 4 4L19 6', close:'m6 6 12 12 M18 6 6 18',
  more:'M5 12h.01 M12 12h.01 M19 12h.01', trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',
  heart:'M12 21 3 12a5 5 0 0 1 9-7 5 5 0 0 1 9 7Z',
  spark:'m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5Z',
  info:'M12 11v6 M12 7h.01 M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20',
  download:'M12 3v12 m-5-5 5 5 5-5 M4 15v6h16v-6',
  snow:'M12 2v20 M3 7l18 10 M3 17 21 7 M9 4l3 3 3-3 M9 20l3-3 3 3',
};
const icon = (name,cls='') => `<svg class="${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.leaf}"/></svg>`;
const KEY='food-saver-v1';
const byId=id=>CATALOG.find(g=>g.id===id);
function localDate(date=new Date()){return `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;}
function future(days){const d=new Date();d.setDate(d.getDate()+Number(days));return localDate(d);}
function expiryTime(item){return new Date(`${item.expiry}T23:59:59`).getTime();}
function remaining(item){return expiryTime(item)-Date.now();}
function countdown(item){const ms=remaining(item);if(ms<=0)return 'Past date';const h=Math.floor(ms/3600000),m=Math.floor(ms/60000)%60;return h>=24?`${Math.floor(h/24)}d ${String(h%24).padStart(2,'0')}h`:`${h}h ${String(m).padStart(2,'0')}m`;}
function daysLeft(item){const [y,m,d]=item.expiry.split('-').map(Number);const now=new Date();return Math.round((Date.UTC(y,m-1,d)-Date.UTC(now.getFullYear(),now.getMonth(),now.getDate()))/86400000);}
function urgency(item){return remaining(item)<=0?'past':daysLeft(item)<=2?'urgent':daysLeft(item)<=state.settings.leadDays?'soon':'fresh';}
function shortDate(date){return new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric'});}
function newState(demo=true){
  const sample=[['avocado',2,'pcs',1,'Pantry'],['spinach',200,'g',1,'Fridge'],['milk',500,'ml',2,'Fridge'],['strawberry',250,'g',2,'Fridge'],['egg',6,'pcs',7,'Fridge'],['bread',1,'loaf',5,'Pantry'],['tomato',3,'pcs',4,'Fridge'],['pasta',500,'g',120,'Pantry'],['olive-oil',1,'bottle',180,'Pantry'],['salt',1,'jar',365,'Pantry'],['black-pepper',1,'jar',365,'Pantry'],['lemon',2,'pcs',8,'Fridge']];
  return {version:1,demo,inventory:demo?sample.filter(s=>byId(s[0])).map(([groceryId,quantity,unit,days,storage])=>({...byId(groceryId),groceryId,id:crypto.randomUUID(),quantity,unit,expiry:future(days),source:'estimated',storage,addedAt:new Date().toISOString()})):[],shopping:[],used:0,settings:{profile:'Individual',track:'all',recipes:true,shopping:true,reminders:true,leadDays:3}};
}
let state;
try{state=JSON.parse(localStorage.getItem(KEY));if(!state||state.version!==1||!Array.isArray(state.inventory)||!state.settings)state=newState();}catch{state=newState();}
let page=location.hash.slice(1)||'home',query='',storageFilter='All',category='All',sort='expiry',recipeMode='flexible',recipeQuery='',diet='All';
let selectedGrocery=null,editing=null,toastTimer,undoAction=null;
function save(){const notice=$('#storage-notice');try{localStorage.setItem(KEY,JSON.stringify(state));notice.hidden=true;notice.innerHTML='';return true;}catch{notice.innerHTML=`${icon('info')}<p><strong>Changes aren’t saved on this device.</strong> They’re available for this session only. Open <a href="#settings">Preferences</a> to export a backup before closing Food Saver.</p>`;notice.hidden=false;return false;}}
function toast(message,undo=null){clearTimeout(toastTimer);undoAction=undo;$('#toast').innerHTML=`<span>${esc(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),undo?8500:4200);}
function visibleFood(){return state.inventory.filter(f=>state.settings.track==='all'||f.perishable!==false);}
function usableFood(){return state.inventory.filter(f=>remaining(f)>0&&Number(f.quantity)>0);}
function soonFood(){return visibleFood().filter(f=>daysLeft(f)<=state.settings.leadDays).sort((a,b)=>expiryTime(a)-expiryTime(b));}
function orderedFood(){return visibleFood().slice().sort((a,b)=>expiryTime(a)-expiryTime(b));}
function badge(item){const u=urgency(item);return `<span class="badge ${u}">${icon('clock')}<span data-countdown="${item.id}">${countdown(item)}</span></span>`;}
function foodEmoji(item){return `<span class="food-emoji ${esc(item.category?.toLowerCase())}">${esc(item.emoji||'🥗')}</span>`;}
function navItems(){return [['home','home','Overview'],['food','fridge','My food'],['smart','spark','Smart kitchen'],...(state.settings.recipes?[['recipes','recipes','Recipes']]:[]),...(state.settings.shopping?[['shopping','bag','Shopping list']]:[])];}
function shell(){
  const nav=navItems();
  $('#sidebar').innerHTML=`<a class="brand" href="#home"><img src="assets/icon.svg" alt="">Food Saver<span class="dot">.</span></a><div class="nav-label">YOUR KITCHEN</div><nav class="side-nav" aria-label="Main navigation">${nav.map(([id,i,label])=>`<a href="#${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${label}${id==='food'?`<span class="nav-count">${visibleFood().length}</span>`:''}</a>`).join('')}</nav><div class="side-divider"></div><a class="nav-link ${page==='settings'?'active':''}" href="#settings">${icon('settings')}Preferences</a><div class="sidebar-bottom"><svg class="plant" viewBox="0 0 60 70"><path d="M30 52V27 M30 36C11 36 12 17 12 17c18 0 18 19 18 19ZM30 29c0-18 18-18 18-18 0 18-18 18-18 18ZM30 45c0-15 16-15 16-15 0 15-16 15-16 15ZM18 52h25l-4 15H22Z"/></svg><h3>A little care.<br>A lot less waste.</h3><p>Small kitchen habits.<br>Good things, every day.</p></div><div class="version">YOUR FOOD, WELL LOOKED AFTER</div>`;
  $('#topbar').innerHTML=`<div class="eyebrow">A little less waste. A little more good.</div><a class="brand mobile-brand" href="#home"><img src="assets/icon.svg" alt="">Food Saver<span class="dot">.</span></a><div class="top-right"><span class="today">${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</span><button class="icon-button" data-action="reminders" aria-label="Expiry reminders">${icon('bell')}${state.settings.reminders&&soonFood().length?'<span class="notification-dot"></span>':''}</button><button class="profile-btn" data-action="preferences" aria-label="Kitchen preferences"><span class="avatar">${icon('user')}</span><span class="profile-name">My kitchen</span>${icon('down')}</button></div>`;
  $('#mobile-nav').innerHTML=nav.map(([id,i,label])=>`<a href="#${id}" class="mobile-nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}${id==='home'?'Home':id==='shopping'?'List':label}</a>`).join('');
}
function heading(title,subtitle,action=true){return `<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action?`<button class="btn btn-primary" data-action="add">${icon('plus')}Add food</button>`:''}</div>`;}
function sampleBar(){return state.demo?`<div class="demo-bar"><span>${icon('info')}You’re exploring a sample kitchen.</span><button data-action="start-fresh">Start my own kitchen ${'→'}</button></div>`:'';}
function row(item){return `<button class="food-row" data-action="edit" data-id="${item.id}">${foodEmoji(item)}<span><span class="food-name">${esc(item.name)}</span><span class="food-meta" style="display:block">${esc(item.quantity)} ${esc(item.unit)} <span aria-hidden="true">·</span> ${esc(item.storage)}</span></span><span class="row-end">${badge(item)}<span class="date-note" style="display:block">${item.source==='estimated'?'Est. ':''}${shortDate(item.expiry)}</span></span></button>`;}
function empty(title,message,action='add',label='Add your first food',i='fridge'){return `<div class="empty">${icon(i)}<h3>${title}</h3><p>${message}</p><button class="btn btn-primary" data-action="${action}">${icon('plus')}${label}</button></div>`;}
function recipeCard(recipe){const m=recipeMatch(recipe,usableFood());return `<article class="recipe-card"><div class="recipe-image"><img src="${esc(recipe.image)}" alt="${esc(recipe.title)}" loading="lazy"><span class="match-chip">${m.missing.length===0?'All ingredients ready':`${m.matched} of ${m.total} ingredients ready`}</span></div><div class="recipe-copy"><h3>${esc(recipe.title)}</h3>${page==='recipes'?`<p class="recipe-desc">${esc(recipe.description)}</p>`:''}<div class="recipe-details"><span>${icon('clock')}${recipe.minutes} min</span><span>${icon('user')}${recipe.servings} servings</span></div><button class="text-link" data-action="recipe" data-id="${recipe.id}">View recipe ${icon('arrow')}</button></div></article>`;}
function bestRecipes(){return RECIPES.slice().sort((a,b)=>recipeMatch(b,usableFood()).percent-recipeMatch(a,usableFood()).percent);}
function renderSmart(){const ranked=rescueRecipes(usableFood(),RECIPES),plan=weeklyMealPlan(usableFood(),RECIPES),alerts=expiryDigest(state.inventory,state.settings.leadDays);return heading('Smart kitchen','Offline-first ideas from your groceries.',false)+sampleBar()+`<h2>🥘 Leftover Rescue</h2><p>Use soon-to-expire ingredients first. Verify food safety and quantities.</p><div class="recipe-preview">${ranked.slice(0,3).map(r=>recipeCard(r.recipe)).join('')}</div><h2>📅 Weekly meal ideas</h2><div class="food-list">${plan.map(p=>`<button class="food-row" data-action="recipe" data-id="${esc(p.recipe.id)}"><span>Day ${p.day}</span><strong>${esc(p.recipe.title)}</strong><span>${p.matched}/${p.total} ingredients</span></button>`).join('')}</div><h2>⏰ Expiry watch</h2><p>${alerts.length} items need attention.</p><div class="food-list">${alerts.slice(0,5).map(row).join('')}</div>`;}
function renderHome(){const soon=soonFood(),food=visibleFood();return heading('Good food. Less waste.','A little overview of the good things in your kitchen.')+sampleBar()+`<section class="hero" aria-label="Make the most of your food"><img class="hero-photo" src="assets/hero.jpg" alt="A fresh bowl of colourful vegetables"><div class="hero-photo-mask"></div><div class="hero-copy"><div class="eyebrow">${icon('leaf')}Good habits start here</div><h2 class="hero-title">A little planning.<br>A fresher kitchen.</h2><p>Keep the good food going. Start with what<br>you already have.</p><button class="btn btn-outline" data-action="use-soon">See what’s expiring ${icon('arrow')}</button></div><span class="hero-stamp">${icon('heart')}Good for you. Kinder to the planet.</span></section><section class="stats" aria-label="Kitchen at a glance"><div class="stat"><span class="stat-icon">${icon('fridge')}</span><div><div class="stat-number">${food.length}</div><div class="stat-label">Items in your kitchen</div></div></div><div class="stat"><span class="stat-icon amber">${icon('clock')}</span><div><div class="stat-number">${soon.length}</div><div class="stat-label">Need a little attention</div></div></div><div class="stat"><span class="stat-icon olive">${icon('leaf')}</span><div><div class="stat-number">${state.used}</div><div class="stat-label">Items used & enjoyed</div></div></div></section><div class="dashboard-grid"><section><div class="section-top"><div><div class="section-kicker">${icon('clock')}<h2>Use these first</h2></div><p class="small-copy">A little nudge before the good stuff goes.</p></div><a class="text-link" href="#food">All food ${icon('arrow')}</a></div>${soon.length?`<div class="food-list">${soon.slice(0,4).map(row).join('')}</div>`:food.length?`<div class="empty">${icon('leaf')}<h3>Looking fresh.</h3><p>No food is nearing its date. Your countdowns will keep you in the loop.</p><a href="#food" class="text-link">Explore your kitchen ${icon('arrow')}</a></div>`:empty('Your fresh start.','Add a few groceries and we’ll help you keep track of what to use first.')}</section><section><div class="section-top"><div><h2>Something delicious?</h2><p class="small-copy">A little inspiration from your kitchen.</p></div>${state.settings.recipes?`<a class="text-link" href="#recipes">Recipes ${icon('arrow')}</a>`:''}</div>${state.settings.recipes?`<div class="recipe-preview">${bestRecipes().slice(0,3).map(recipeCard).join('')}</div>`:`<div class="empty">${icon('recipes')}<h3>Recipes, your way.</h3><p>Recipe suggestions are switched off. You can enable them in preferences.</p><a href="#settings" class="text-link">Preferences ${icon('arrow')}</a></div>`}</section></div><aside class="tip-banner">${icon('leaf')}<p><strong>A small habit, a big difference.</strong> Keep soon-to-expire food at the front of your fridge so it’s the first thing you reach for.</p></aside>`;}
function renderFood(){let food=visibleFood().filter(f=>(storageFilter==='All'||f.storage===storageFilter)&&(category==='All'||f.category===category)&&f.name.toLowerCase().includes(query.toLowerCase()));food.sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='added'?new Date(b.addedAt)-new Date(a.addedAt):expiryTime(a)-expiryTime(b));return heading('A home for your food.','Know what you have. Make the most of every ingredient.')+sampleBar()+`<div class="tabs" role="group" aria-label="Storage location">${['All','Fridge','Freezer','Pantry'].map(s=>`<button class="tab ${storageFilter===s?'active':''}" data-action="storage-filter" data-value="${s}" aria-pressed="${storageFilter===s}">${icon(s==='Freezer'?'snow':s==='Fridge'?'fridge':s==='Pantry'?'bag':'leaf')}${s}<span class="pill-count">${visibleFood().filter(f=>s==='All'||f.storage===s).length}</span></button>`).join('')}</div><div class="filter-bar"><div class="search-wrap">${icon('search')}<input class="input" id="food-search" aria-label="Search your food" placeholder="Find something in your kitchen…" value="${esc(query)}"></div><select class="select" id="category-filter" aria-label="Filter by category">${['All','Produce','Dairy','Protein','Grains','Pantry','Frozen'].map(c=>`<option ${category===c?'selected':''}>${c}</option>`).join('')}</select><select class="select" id="sort-food" aria-label="Sort food"><option value="expiry" ${sort==='expiry'?'selected':''}>Expiring first</option><option value="name" ${sort==='name'?'selected':''}>Name A–Z</option><option value="added" ${sort==='added'?'selected':''}>Recently added</option></select></div><p class="result-count">${food.length} ${food.length===1?'item':'items'}${state.settings.track==='perishable'?' · Perishable food only':''}</p>${food.length?`<div class="food-grid">${food.map(f=>`<article class="item-card"><div class="item-top">${foodEmoji(f)}<span class="badge ${urgency(f)}">${esc(f.storage)}</span></div><h3>${esc(f.name)}</h3><p class="item-sub">${esc(f.quantity)} ${esc(f.unit)} · ${esc(f.category)}</p><div class="countdown-box ${urgency(f)}"><span>${remaining(f)<=0?'Date has passed':'Time until expiry'}</span><strong data-countdown="${f.id}">${countdown(f)}</strong></div><p class="expiry-note">${f.source==='estimated'?'Estimated date':'Packaging date'} · ${shortDate(f.expiry)}</p><div class="item-actions"><button class="text-link" data-action="used" data-id="${f.id}">${icon('check')}Used it</button><button class="icon-button" data-action="edit" data-id="${f.id}" aria-label="Edit ${esc(f.name)}">${icon('more')}</button></div></article>`).join('')}</div>`:empty(query||storageFilter!=='All'||category!=='All'?'Nothing here just yet.':'Your kitchen starts here.',query?'Try another search, or add something new.':'Search the grocery catalogue to add food and start its countdown.')}`;}
function renderRecipes(){if(!state.settings.recipes)return disabled('Recipe suggestions');let recipes=bestRecipes().filter(r=>r.title.toLowerCase().includes(recipeQuery.toLowerCase())&&(diet==='All'||r.diet===diet)&&(recipeMode==='flexible'||recipeMatch(r,usableFood()).missing.length===0));return heading('Make something good.','A little inspiration. A lot of delicious possibilities.',false)+`<div class="recipe-mode"><div><h3>What’s cooking?</h3><p>Choose how adventurous you’d like to be.</p></div><div class="segmented" role="group" aria-label="Recipe ingredient mode"><button class="${recipeMode==='strict'?'active':''}" data-action="recipe-mode" data-value="strict" aria-pressed="${recipeMode==='strict'}">Only my ingredients</button><button class="${recipeMode==='flexible'?'active':''}" data-action="recipe-mode" data-value="flexible" aria-pressed="${recipeMode==='flexible'}">A few extras are okay</button></div></div><div class="filter-bar"><div class="search-wrap">${icon('search')}<input class="input" id="recipe-search" placeholder="Find your next favourite meal…" aria-label="Search recipes" value="${esc(recipeQuery)}"></div><select class="select" id="diet-filter" aria-label="Recipe dietary preference">${['All','Vegan','Vegetarian','Non-vegetarian'].map(d=>`<option ${diet===d?'selected':''}>${d}</option>`).join('')}</select></div><p class="result-count">${recipes.length} recipes · Matches check ingredient types in your kitchen; review quantities before cooking.</p>${recipes.length?`<div class="recipe-grid">${recipes.map(recipeCard).join('')}</div>`:empty('A little more to work with.','No recipes match these choices yet. Add your ingredients, or allow a few extras.','flexible-recipes','Allow a few extras','recipes')}`;}
function renderShopping(){if(!state.settings.shopping)return disabled('Shopping lists');const pending=state.shopping.filter(s=>!s.checked),done=state.shopping.filter(s=>s.checked);return heading('A thoughtful little list.','Just what you need for your next kitchen adventure.',false)+`<div class="shopping-layout"><section><form id="shopping-form" class="shopping-form"><div class="search-wrap">${icon('plus')}<input class="input" name="item" placeholder="Add something to your list…" aria-label="Shopping list item" required maxlength="100"></div><button class="btn btn-primary" type="submit">Add item</button></form>${pending.length||done.length?`${shoppingGroup('To pick up',pending)}${shoppingGroup('In your basket',done)}`:empty('Room for something good.','Add what you need above, or find a recipe and we’ll list its missing ingredients.','browse-recipes','Find a recipe','bag')}${done.length?`<button class="text-link" data-action="clear-checked">${icon('check')}Clear checked items</button>`:''}</section><aside class="shopping-side">${icon('bag')}<h2>A little list.<br>A calmer shop.</h2><p>You have <strong>${pending.length} ${pending.length===1?'item':'items'}</strong> left to pick up. Check your kitchen before buying more.</p><button class="btn btn-outline" data-action="copy-list">${icon('download')}Copy shopping list</button><p>Lists are saved on this device, ready whenever you need them.</p></aside></div>`;}
function shoppingGroup(title,items){return items.length?`<section class="shopping-group"><h3>${title} · ${items.length}</h3>${items.map(s=>`<div class="shopping-row"><button class="check ${s.checked?'checked':''}" data-action="check-shopping" data-id="${s.id}" role="checkbox" aria-checked="${s.checked}" aria-label="${esc(s.name)}">${s.checked?icon('check'):''}</button><span class="shopping-name ${s.checked?'checked-label':''}">${esc(s.name)}</span><button class="icon-button" data-action="delete-shopping" data-id="${s.id}" aria-label="Remove ${esc(s.name)}">${icon('close')}</button></div>`).join('')}</section>`:'';}
function disabled(feature){return heading('Your kitchen, your way.',`${feature} are currently switched off.`,false)+`<div class="empty">${icon('settings')}<h3>Make room for what you need.</h3><p>You can switch this feature back on in preferences.</p><a class="btn btn-primary" href="#settings">Open preferences</a></div>`;}
function switchRow(key,title,description){return `<div class="setting-row"><div><h3>${title}</h3><p>${description}</p></div><button class="switch ${state.settings[key]?'on':''}" role="switch" aria-checked="${state.settings[key]}" aria-label="${title}" data-action="toggle-setting" data-key="${key}"><span></span></button></div>`;}
function renderSettings(){return heading('Your kitchen, your way.','A few little preferences to make Food Saver feel like home.',false)+`<div class="settings-layout"><section class="settings-card"><h2>Make yourself at home</h2><p>A kitchen companion for every kind of household.</p><div class="setting-row"><div><h3>Your kitchen profile</h3><p>Choose what suits you. Change it anytime.</p></div><select class="select" id="profile-setting" aria-label="Kitchen profile">${['Individual','Student','Family','Roommates','Other'].map(p=>`<option ${state.settings.profile===p?'selected':''}>${p}</option>`).join('')}</select></div><div class="setting-row"><div><h3>What would you like to track?</h3><p>Keep everything, or focus on perishable food.</p></div><select class="select" id="tracking-setting" aria-label="Food tracking scope"><option value="all" ${state.settings.track==='all'?'selected':''}>My whole kitchen</option><option value="perishable" ${state.settings.track==='perishable'?'selected':''}>Perishables only</option></select></div></section><section class="settings-card"><h2>Keep what works for you</h2>${switchRow('recipes','Recipe suggestions','Find something delicious with what you have.')}${switchRow('shopping','Shopping lists','Keep track of what you need to pick up.')}${switchRow('reminders','In-app expiry reminders','Show upcoming dates in your reminder centre.')}<div class="setting-row"><div><h3>Give me a little heads-up</h3><p>How early should food appear in “Use these first”?</p></div><select id="lead-setting" class="select" aria-label="Expiry reminder timing">${[1,2,3,5,7].map(d=>`<option value="${d}" ${state.settings.leadDays===d?'selected':''}>${d} ${d===1?'day':'days'} before</option>`).join('')}</select></div><p class="inline-note">Reminders appear while you’re using the app. Background push notifications are not enabled.</p></section><section class="settings-card"><h2>Your kitchen data</h2><p>${state.demo?'You’re exploring sample groceries. Start fresh when you’re ready to add your own.':'Your food, lists, and preferences are saved in this browser on this device.'}</p><div class="settings-actions"><button class="btn btn-outline" data-action="export">${icon('download')}Export my data</button><button class="btn btn-light" data-action="load-sample">Explore sample kitchen</button><button class="btn btn-danger" data-action="reset">Clear kitchen data</button></div><div class="storage-note">${icon('info')}This first version stores data on your device. Profiles don’t create shared accounts or sync between people.</div></section></div>`;}
function render(){if(!['home','food','recipes','shopping','settings','smart'].includes(page))page='home';shell();$('#main').innerHTML=({home:renderHome,food:renderFood,recipes:renderRecipes,shopping:renderShopping,settings:renderSettings,smart:renderSmart}[page])();}
function go(target){if(page===target){render();window.scrollTo(0,0);}else location.hash=target;}
window.addEventListener('hashchange',()=>{page=location.hash.slice(1)||'home';render();window.scrollTo({top:0,behavior:'instant'});});
function openDialog(title,body){$('#modal').innerHTML=`<div class="dialog-top"><h2>${title}</h2><button class="icon-button" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!$('#modal').open)$('#modal').showModal();}
function closeDialog(){$('#modal').close();}
function addDialog(){editing=null;selectedGrocery=null;openDialog('Something fresh?',`<p class="subtitle">Search your groceries and give them a home.</p>${state.demo?'<p class="inline-note">Adding your first food starts your own kitchen and replaces the sample groceries.</p>':''}<div class="search-wrap">${icon('search')}<input id="catalog-search" class="input" placeholder="Try avocado, milk, or strawberries…" aria-label="Search grocery catalogue" autocomplete="off"></div><div id="catalog-results" class="catalog-results"></div>`);catalogResults('');setTimeout(()=>$('#catalog-search')?.focus(),50);}
function catalogResults(text){const found=CATALOG.filter(g=>(g.name.toLowerCase().includes(text.toLowerCase())||g.id.includes(text.toLowerCase()))).slice(0,text?20:8);$('#catalog-results').innerHTML=found.map(g=>`<button class="catalog-item" data-action="choose-grocery" data-id="${g.id}">${foodEmoji(g)}<span>${esc(g.name)}</span><span class="category">${esc(g.category)}</span>${icon('plus')}</button>`).join('')+(text.trim()?`<button class="catalog-item" data-action="custom-grocery" data-value="${esc(text.trim())}">${icon('plus')}Add “${esc(text.trim())}” as a custom food</button>`:'');}
function foodForm(grocery,item=null){selectedGrocery=grocery;editing=item?.id||null;const initialSource=item?.source||'estimated',initialDays=item?Math.max(0,Math.round((new Date(item.expiry+'T12:00:00')-new Date(localDate()+'T12:00:00'))/86400000)):grocery.shelfLife;openDialog(item?'A little update.':'Give it a home.',`<div class="chosen-food">${foodEmoji(grocery)}<div><h3>${esc(grocery.name)}</h3><p>${esc(grocery.category)}</p></div>${!item?'<button class="text-link" data-action="add">Change</button>':''}</div><form id="food-form"><div class="form-row"><label class="field"><span>Quantity</span><input name="quantity" class="input" type="number" min="0.01" max="1000000" step="any" value="${item?.quantity||(grocery.unit==='g'?100:grocery.unit==='ml'?500:1)}" required></label><label class="field"><span>Unit</span><select class="select" name="unit">${[...new Set([item?.unit||grocery.unit,'pcs','g','kg','ml','L','pack','bottle','jar','loaf'])].map(u=>`<option>${esc(u)}</option>`).join('')}</select></label></div><label class="field"><span>Where will it live?</span><select class="select" name="storage">${['Fridge','Freezer','Pantry'].map(s=>`<option ${(item?.storage||(grocery.perishable?'Fridge':'Pantry'))===s?'selected':''}>${s}</option>`).join('')}</select></label><span class="field-label">How would you like to set the date?</span><div class="segmented" style="margin-bottom:17px" role="group" aria-label="Expiry date method"><button type="button" class="${initialSource==='packaging'?'active':''}" data-action="date-mode" data-value="packaging">Date on packaging</button><button type="button" class="${initialSource==='estimated'?'active':''}" data-action="date-mode" data-value="estimated">Editable estimate</button></div><input type="hidden" name="source" value="${initialSource}"><label class="field" id="estimate-field" ${initialSource==='packaging'?'hidden':''}><span>Suggested days from today</span><input type="number" class="input" name="days" value="${initialDays}" min="0" max="3650" step="1" ${initialSource==='packaging'?'disabled':''}><small>An approximate shelf life. Adjust for the packaging and where you store it.</small></label><label class="field"><span id="date-label">${initialSource==='packaging'?'Date on packaging':'Estimated expiry date'}</span><input type="date" class="input" name="expiry" value="${item?.expiry||future(grocery.shelfLife)}" required min="2000-01-01" max="2100-12-31"></label><div class="date-preview"><span>Your expiry countdown</span><strong id="date-preview-countdown">${countdown({expiry:item?.expiry||future(grocery.shelfLife)})}</strong></div><div class="form-actions">${item?`<button type="button" class="btn btn-danger" data-action="delete-food" data-id="${item.id}" aria-label="Remove food">${icon('trash')}</button>`:'<button type="button" class="btn btn-outline" data-action="close">Cancel</button>'}<button class="btn btn-primary" type="submit">${icon(item?'check':'plus')}${item?'Save changes':'Add to my food'}</button></div></form>`);}
function saveFood(form){if(!form.reportValidity())return;const data=new FormData(form),qty=Number(data.get('quantity'));if(!(qty>0)||!Number.isFinite(qty))return;const entry={...selectedGrocery,groceryId:selectedGrocery.groceryId||selectedGrocery.id,id:editing||crypto.randomUUID(),quantity:qty,unit:data.get('unit'),storage:data.get('storage'),expiry:data.get('expiry'),source:data.get('source'),addedAt:editing?state.inventory.find(f=>f.id===editing).addedAt:new Date().toISOString()};if(!editing&&state.demo){state.inventory=[];state.used=0;state.demo=false;}if(editing)state.inventory=state.inventory.map(f=>f.id===editing?entry:f);else state.inventory.push(entry);save();closeDialog();render();toast(editing?'Your food has been updated.':`${entry.name} is now in your kitchen.`);}
function removeFood(id,used=false){const item=state.inventory.find(f=>f.id===id);if(!item)return;const index=state.inventory.indexOf(item);state.inventory.splice(index,1);if(used)state.used++;save();closeDialog();render();toast(used?`${item.name}, used & enjoyed.`:`${item.name} removed.`,()=>{state.inventory.splice(index,0,item);if(used)state.used=Math.max(0,state.used-1);save();render();toast('Food restored to your kitchen.');});}
function recipeDialog(id){const r=RECIPES.find(r=>r.id===id);if(!r)return;const m=recipeMatch(r,usableFood());openDialog(esc(r.title),`<img src="${esc(r.image)}" class="recipe-modal-image" alt="${esc(r.title)}"><div class="detail-meta"><span>${icon('clock')}${r.minutes} minutes</span><span>${icon('user')}${r.servings} servings</span><span>${esc(r.diet)}</span></div><p class="onboarding-copy">${esc(r.description)}</p><h3 class="detail-section">A few good ingredients</h3><p class="inline-note">${m.matched} of ${m.total} ingredient types in your kitchen. Check quantities before cooking.</p>${r.ingredients.map(ingredient=>{const g=byId(ingredient.id);return `<div class="ingredient-row">${m.available.some(a=>a.id===ingredient.id)?icon('check'):'<span class="missing-dot"></span>'}<span>${esc(g?.name||ingredient.id)}</span><span class="amount">${esc(ingredient.amount)}</span></div>`;}).join('')}${state.settings.shopping&&m.missing.length?`<button class="btn btn-outline full-width" style="margin-top:16px" data-action="recipe-shopping" data-id="${r.id}">${icon('plus')}Add ${m.missing.length} missing ingredients to list</button>`:''}<h3 class="detail-section">Let’s make it</h3><ol class="steps">${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`);}
function addShopping(name){name=name.trim().slice(0,100);if(!name)return false;if(state.shopping.some(s=>s.name.toLowerCase()===name.toLowerCase()&&!s.checked))return false;state.shopping.push({id:crypto.randomUUID(),name,checked:false});return true;}
function addRecipeShopping(id){const recipe=RECIPES.find(r=>r.id===id),m=recipeMatch(recipe,usableFood());let count=0;for(const ingredient of m.missing){if(addShopping(`${byId(ingredient.id).name} — ${ingredient.amount}`))count++;}save();toast(count?`${count} ingredients added to your shopping list.`:'Those ingredients are already on your list.');}
function remindersDialog(){const soon=soonFood();openDialog('A little heads-up.',state.settings.reminders?`<p class="onboarding-copy">Food within ${state.settings.leadDays} days of its date, including dates that have passed.</p><div id="reminder-list">${soon.length?soon.map(row).join(''):'<div class="empty">'+icon('leaf')+'<h3>Looking fresh.</h3><p>Nothing needs your attention just yet.</p></div>'}</div><p class="inline-note">Countdowns follow the dates you set. Estimates are marked separately.</p>`:`<p class="onboarding-copy">In-app reminders are switched off. Enable them in preferences whenever you’d like.</p><button class="btn btn-primary" data-action="preferences">Open preferences</button>`);}
function confirmDialog(title,description,action,label){openDialog(title,`<p class="onboarding-copy">${description}</p><div class="form-actions"><button class="btn btn-outline" data-action="close">Keep my kitchen</button><button class="btn btn-primary" data-action="${action}">${label}</button></div>`);}
document.addEventListener('click',async event=>{
  const button=event.target.closest('[data-action]');if(!button)return;const {action,id,value,key}=button.dataset;
  if(action==='close')closeDialog();
  else if(action==='add')addDialog();
  else if(action==='choose-grocery')foodForm(byId(id));
  else if(action==='custom-grocery')foodForm({id:`custom-${crypto.randomUUID()}`,name:value,category:'Pantry',emoji:'🥗',shelfLife:7,unit:'pcs',perishable:true});
  else if(action==='edit'){const item=state.inventory.find(f=>f.id===id);if(item)foodForm(item,item);}
  else if(action==='used')removeFood(id,true);
  else if(action==='delete-food')removeFood(id);
  else if(action==='undo'){if(undoAction){const fn=undoAction;undoAction=null;fn();}}
  else if(action==='preferences'){closeDialog();go('settings');}
  else if(action==='reminders')remindersDialog();
  else if(action==='use-soon'){remindersDialog();}
  else if(action==='storage-filter'){storageFilter=value;render();}
  else if(action==='recipe'){recipeDialog(id);}
  else if(action==='recipe-mode'){recipeMode=value;render();}
  else if(action==='flexible-recipes'){recipeMode='flexible';go('recipes');}
  else if(action==='browse-recipes'){go(state.settings.recipes?'recipes':'settings');}
  else if(action==='recipe-shopping')addRecipeShopping(id);
  else if(action==='check-shopping'){const entry=state.shopping.find(s=>s.id===id);entry.checked=!entry.checked;save();render();}
  else if(action==='delete-shopping'){const entry=state.shopping.find(s=>s.id===id),index=state.shopping.indexOf(entry);state.shopping.splice(index,1);save();render();toast('Item removed from your list.',()=>{state.shopping.splice(index,0,entry);save();render();});}
  else if(action==='clear-checked'){const old=state.shopping.slice();state.shopping=state.shopping.filter(s=>!s.checked);save();render();toast('Checked items cleared.',()=>{state.shopping=old;save();render();});}
  else if(action==='copy-list'){const text=state.shopping.filter(s=>!s.checked).map(s=>`☐ ${s.name}`).join('\n');if(!text){toast('Your list is empty.');return;}try{await navigator.clipboard.writeText(text);toast('Shopping list copied.');}catch{openDialog('Your shopping list',`<p class="onboarding-copy">Select and copy your list below.</p><textarea class="input" rows="10" aria-label="Shopping list to copy" readonly>${esc(text)}</textarea>`);}}
  else if(action==='date-mode'){const form=$('#food-form');form.elements.source.value=value;form.elements.days.disabled=value==='packaging';$('#estimate-field').hidden=value==='packaging';$('#date-label').textContent=value==='packaging'?'Date on packaging':'Estimated expiry date';form.querySelectorAll('[data-action="date-mode"]').forEach(b=>b.classList.toggle('active',b.dataset.value===value));}
  else if(action==='toggle-setting'){state.settings[key]=!state.settings[key];save();render();}
  else if(action==='start-fresh'){confirmDialog('A fresh start.','This will replace sample groceries with your own empty kitchen. You can explore the sample again from preferences.','confirm-fresh','Start my kitchen');}
  else if(action==='confirm-fresh'){const settings=state.settings,shopping=state.shopping;state=newState(false);state.settings=settings;state.shopping=shopping;save();closeDialog();render();addDialog();}
  else if(action==='load-sample'){confirmDialog('Explore a sample kitchen?','This replaces the food and lists on this device with example groceries. Export your current data first if you want to keep a copy.','confirm-sample','Load sample kitchen');}
  else if(action==='confirm-sample'){state=newState(true);save();closeDialog();go('home');toast('You’re exploring the sample kitchen.');}
  else if(action==='reset'){confirmDialog('Clear this kitchen?','This removes your food, shopping list, and preferences from this device.','confirm-reset','Clear kitchen data');}
  else if(action==='confirm-reset'){state=newState(false);save();closeDialog();go('home');toast('Your kitchen has been cleared.');}
  else if(action==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`food-saver-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your kitchen data has been exported.');}
});
document.addEventListener('submit',event=>{if(event.target.id==='food-form'){event.preventDefault();saveFood(event.target);}if(event.target.id==='shopping-form'){event.preventDefault();const input=event.target.elements.item;if(addShopping(input.value)){save();render();toast('Added to your shopping list.');$('#shopping-form input')?.focus();}else toast('That item is already on your list.');}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='catalog-search')catalogResults(el.value);if(el.id==='food-search'){query=el.value;renderKeepingFocus('food-search',el.selectionStart);}if(el.id==='recipe-search'){recipeQuery=el.value;renderKeepingFocus('recipe-search',el.selectionStart);}if(el.closest('#food-form')&&(el.name==='days'||el.name==='expiry')){const form=$('#food-form');if(el.name==='days'&&el.validity.valid)form.elements.expiry.value=future(el.value);if(el.name==='expiry'&&el.value&&el.validity.valid)form.elements.days.value=Math.max(0,daysLeft({expiry:el.value}));if(form.elements.expiry.value)$('#date-preview-countdown').textContent=countdown({expiry:form.elements.expiry.value});}});
function renderKeepingFocus(id,cursor){render();const input=$('#'+id);input?.focus();input?.setSelectionRange(cursor,cursor);}
document.addEventListener('change',event=>{const el=event.target;if(el.id==='category-filter')category=el.value;else if(el.id==='sort-food')sort=el.value;else if(el.id==='diet-filter')diet=el.value;else if(el.id==='profile-setting')state.settings.profile=el.value;else if(el.id==='tracking-setting')state.settings.track=el.value;else if(el.id==='lead-setting')state.settings.leadDays=Number(el.value);else return;save();render();});
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog();}});
setInterval(()=>{document.querySelectorAll('[data-countdown]').forEach(el=>{const food=state.inventory.find(f=>f.id===el.dataset.countdown);if(food)el.textContent=countdown(food);});},30000);
save();render();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
